-- View Situation Salaire Misy Doublon


CREATE OR REPLACE VIEW "SITUATION_SALAIRE_EDITION" ("ID", "PERSONNEL", "FONCTION", "MATRICULE", "HEUREMOIS", "HEURELEGAL", "HEUREPRESENCE", "TAUXHORAIRE", "SALAIRE", "SALAIREMOIS", "HEURESUP", "RAPPEL", "RETENUABSC", "PRIME", "CONGEPAYER", "PREAVIS", "INDAMDIVFIXE", "SALAIREBRUTE", "CNAPS", "OSTIE", "NETIMPOSABLE", "NETIMPOSABLEARR", "IRSA", "NBENFANT", "IRSANET", "AVANCESALAIRE", "AVANCEEXCEP", "ALLOCATION", "NETPAYER", "NETPAYERARR", "MOIS", "ANNEE") AS
select
    id,
    personnel,
    fonction,
    matricule,
    heuremois,
    heuremois as heurelegal,
    heurepresence,
    tauxhoraire,
    salaire,
    heurepresence*tauxhoraire as salairemois,
    heuresup,
    rappel,
    retenuabsc,
    prime,
    congepayer,
    preavis,
    indamdivfixe,
    salairebrute-nvl(allocation,0) as salairebrute,
    cnaps,
    ostie,
    netimposable,
    netimposablearr,
    irsa,
    nbenfant,
    irsanet,
    avancesalaire,
    avanceexcep,
    allocation as allocation,
    netpayer,
    netpayerarr,
    mois,annee
from TEST_SITUATION_SALAIRE_EDITION;

-- View Situation Salaire Fix Doublon


CREATE OR REPLACE VIEW "SITUATION_SALAIRE_EDITION" ("ID", "PERSONNEL", "FONCTION", "MATRICULE", "HEUREMOIS", "HEURELEGAL", "HEUREPRESENCE", "TAUXHORAIRE", "SALAIRE", "SALAIREMOIS", "HEURESUP", "RAPPEL", "RETENUABSC", "PRIME", "CONGEPAYER", "PREAVIS", "INDAMDIVFIXE", "SALAIREBRUTE", "CNAPS", "OSTIE", "NETIMPOSABLE", "NETIMPOSABLEARR", "IRSA", "NBENFANT", "IRSANET", "AVANCESALAIRE", "AVANCEEXCEP", "ALLOCATION", "NETPAYER", "NETPAYERARR", "MOIS", "ANNEE") AS
SELECT
    id,
    personnel,
    fonction,
    matricule,
    heuremois,
    heuremois as heurelegal,
    heurepresence,
    tauxhoraire,
    salaire,
    heurepresence*tauxhoraire as salairemois,
    heuresup,
    rappel,
    retenuabsc,
    prime,
    congepayer,
    preavis,
    indamdivfixe,
    salairebrute-nvl(allocation,0) as salairebrute,
    cnaps,
    ostie,
    netimposable,
    netimposablearr,
    irsa,
    nbenfant,
    irsanet,
    avancesalaire,
    avanceexcep,
    allocation as allocation,
    netpayer,
    netpayerarr,
    mois,
    annee
FROM (
     SELECT
         id,
         personnel,
         fonction,
         matricule,
         heuremois,
         heurepresence,
         tauxhoraire,
         salaire,
         heuresup,
         rappel,
         retenuabsc,
         prime,
         congepayer,
         preavis,
         indamdivfixe,
         salairebrute,
         cnaps,
         ostie,
         netimposable,
         netimposablearr,
         irsa,
         nbenfant,
         irsanet,
         avancesalaire,
         avanceexcep,
         allocation,
         netpayer,
         netpayerarr,
         mois,
         annee,
         ROW_NUMBER() OVER (PARTITION BY personnel ORDER BY id) as rn
     FROM TEST_SITUATION_SALAIRE_EDITION
) ranked_data
WHERE rn = 1;

